import React from 'react';

const OfferingsSidebar = ({ offerings, onOfferingClick }) => {
  return (
    <div className="lg:col-span-1">
      <div className="bg-white border border-gray-200 rounded-lg p-8 shadow-md">
        <h3 className="text-2xl font-light italic text-gray-800 mb-6">
          What We Offer?
        </h3>
        
        <div className="space-y-4 mb-8">
          {offerings.map((offering) => (
            <button
              key={offering.id}
              onClick={() => onOfferingClick && onOfferingClick(offering.name)}
              className="block w-full text-left text-gray-700 hover:text-[#5dade2] transition-colors border-l-4 border-[#f4d03f] pl-4 py-2 cursor-pointer"
            >
              {offering.name}
            </button>
          ))}
        </div>
        
        <a
          href="tel:+919825814883"
          className="block w-full bg-[#5dade2] hover:bg-[#4a9bd1] text-white py-6 text-sm tracking-wider transition-all text-center rounded"
        >
          CONTACT US
        </a>
      </div>
    </div>
  );
};

export default OfferingsSidebar;
